Author: <a href data-email-masked rel="nofollow">stigl...@hotmail.com</a><br>Date: Tue Feb 24 22:24:01 2009<br>New Revision: 255<p>Added:<br>    trunk/tsDyn/R/selectSETAR.R<br>Modified:<br>    trunk/tsDyn/R/setar.R<p>Log:<br>selectSETAR moved in own file selectSETAR.R instead of setar.R<p>Added: trunk/tsDyn/R/selectSETAR.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/selectSETAR.R	Tue Feb 24 22:24:01 2009<br>@@ -0,0 +1,440 @@<br>+## Copyright (C) 2005/2006/2009  Antonio, Fabio Di Narzo<br>+##<br>+## This program is free software; you can redistribute it and/or modify<br>+## it under the terms of the GNU General Public License as published by<br>+## the Free Software Foundation; either version 2, or (at your option)<br>+## any later version.<br>+##<br>+## This program is distributed in the hope that it will be useful, but<br>+## WITHOUT ANY WARRANTY;without even the implied warranty of<br>+## MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU<br>+## General Public License for more details.<br>+##<br>+## A copy of the GNU General Public License is available via WWW at<br>+## <a href="http://www.gnu.org/copyleft/gpl.html" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://www.gnu.org/copyleft/gpl.html&amp;source=gmail&amp;ust=1792465042833000&amp;usg=AOvVaw2AX1PAIrqDMmDW0GKwTIcZ">http://www.gnu.org/copyleft/gpl.html</a>.  You can also obtain it by<br>+## writing to the Free Software Foundation, Inc., 59 Temple Place,<br>+## Suite 330, Boston, MA  02111-1307  USA.<br>+<br>+<br>+###Exhaustive search over a grid of model parameters<br>+selectSETAR&lt;- function (x, m, d=1, steps=d, series, mL, mH,mM, thDelay=0,  <br>mTh, thVar, th=MakeThSpec(), trace=TRUE, include =  <br>c(&quot;const&quot;, &quot;trend&quot;,&quot;none&quot;, &quot;both&quot;), common=FALSE, model=c(&quot;TAR&quot;, &quot;MTAR&quot;),  <br>ML=seq_len(mL),MH=seq_len(mH), MM=seq_len(mM),nthresh=1,trim=0.15,criterion  <br>= c(&quot;pooled-AIC&quot;, &quot;AIC&quot;, &quot;SSR&quot;),thSteps = 7,ngrid=&quot;ALL&quot;,   <br>plot=TRUE,max.iter=2, type=c(&quot;level&quot;, &quot;diff&quot;, &quot;ADF&quot;), same.lags=FALSE)<br>+#This internal function called by setar() makes a grid search over the  <br>values given by setar or user<br>+#1: Build the regressors matrix, cut Y to adequate (just copy paste of  <br>function setar() )<br>+#2: establish the transition variable z (just copy paste of function  <br>setar() )<br>+#3. set-up the grid following argument th or by default ngrid==&quot;ALL&quot; on  <br>all values<br>+#4: Sets up functions to compute the SSR or AIC on model with 1 or 2  <br>thresh, or Pooled AIC<br>+#5: establish a grid with addition of thDelay (crit SSR) or thDelay, Ml  <br>and Mh  (crit AIC and pooledAIC)<br>+#6: apply the function in 3 to grid in 4<br>+#7: sorts the results to show the best values<br>+#8: Computation for 2 thresh using condiStep (see TVARestim.r)<br>+#9: plot of the results of the grid search<br>+#10: return results<br>+{<br>+### SelectSETAR 0: preliminary checks<br>+  include&lt;-match.arg(include)<br>+  model&lt;-match.arg(model)<br>+  type&lt;-match.arg(type)<br>+  if(missing(m))<br>+    m &lt;- max(ML, MH, ifelse(nthresh==2, max(MM),0),thDelay+1)<br>+  if(missing(series))<br>+      series &lt;- deparse(substitute(x))<br>+<br>+  if (criterion == &quot;pooled-AIC&quot;&amp;nthresh==2){<br>+      warning(&quot;
criterion pooled AIC currently not implemented for  <br>nthresh=2, criterion SSR is used
&quot;)<br>+      criterion&lt;-&quot;SSR&quot;<br>+    }<br>+### SelectSETAR 1:  Build the regressors matrix, cut Y to adequate (just  <br>copy paste of function setar() )<br>+	str &lt;- nlar.struct(x=x, m=m, d=d, steps=steps, series=series)<br>+	<br>+	if(type==&quot;level&quot;){<br>+	  xx &lt;- getXX(str)<br>+	  yy &lt;- getYY(str)<br>+	}<br>+	else{<br>+	  if(type==&quot;diff&quot;){<br>+	    xx &lt;- getdXX(str)<br>+	    yy &lt;- getdYY(str)<br>+	  }<br>+	  else if(type==&quot;ADF&quot;){<br>+	    xx &lt;- cbind(getdX1(str),getdXX(str))<br>+	    yy &lt;- getdYY(str)<br>+	  }<br>+	  str$xx&lt;-xx<br>+	  str$yy&lt;-yy<br>+	}<br>+	<br>+  externThVar &lt;- FALSE<br>+<br>+##SelectSETAR: Lags selection<br>+#<br>+#   if(criterion==&quot;SSR&quot;&amp;nthresh==2){<br>+#     if(missing(m)&amp;all(missing(MM),missing(mM)))<br>+#       stop(&quot;With criterion SSR, for 2 threholds, number of lags in inner  <br>regime has to be given&quot;)<br>+#   }<br>+<br>+  ###ML<br>+  if(missing(ML)) {		#ML: different lags<br>+    if (missing(mL)) {	#mL: suit of lags<br>+      if(missing(m))<br>+	cat(&quot;arg m is missing&quot;)<br>+      else<br>+	mL &lt;- m<br>+      if (trace)<br>+	cat(&quot;Using maximum autoregressive order for low regime: mL =&quot;, m,&quot;
&quot;)<br>+    }<br>+    ML &lt;- seq_len(mL)<br>+  }<br>+<br>+  ###MH<br>+  if(missing(MH)) {<br>+    if (missing(mH)) {<br>+    mH &lt;- m<br>+      if (trace)<br>+	cat(&quot;Using maximum autoregressive order for high regime: mH =&quot;, m,&quot;
&quot;)<br>+    }<br>+  MH &lt;- seq_len(mH)<br>+  }<br>+<br>+  ###MM<br>+  if(missing(MM)) {<br>+    if (missing(mM)) {<br>+    mM &lt;- m<br>+      if (trace&amp;nthresh==2)<br>+	cat(&quot;Using maximum autoregressive order for middle regime: mM =&quot;, m,&quot;
&quot;)<br>+    }<br>+  MM &lt;- seq_len(mM)<br>+  }<br>+<br>+<br>+   <br>if(!all(isTRUE(all.equal(ML,MM))&amp;isTRUE(all.equal(ML,MH)))&amp;same.lags==TRUE)<br>+    stop(&quot;Arg same.lag set to true but different lags given. Choose either  <br>one of those&quot;)<br>+<br>+  if(criterion==&quot;SSR&quot;)<br>+    same.lags&lt;- if(isTRUE(all.equal(ML,MM))&amp;isTRUE(all.equal(ML,MH))) TRUE  <br>else FALSE<br>+<br>+<br>+###SelectSETAR: includes const, trend<br>+  if(include==&quot;none&quot; &amp;&amp; any(c(ML,MM,MH)==0))<br>+    stop(&quot;you cannot have a regime without constant and lagged variable&quot;)<br>+  constMatrix&lt;-buildConstants(include=include, n=nrow(xx)) #stored in  <br>miscSETAR.R<br>+  incNames&lt;-constMatrix$incNames #vector of names<br>+  const&lt;-constMatrix$const #matrix of none, const, trend, both<br>+  ninc&lt;-constMatrix$ninc #number of terms (0,1, or 2)<br>+<br>+### selectSETAR 2: Set-up of transition variable<br>+#two models: TAR or MTAR (z is differenced)<br>+#three possibilitiees for thVar:<br>+#thDelay: scalar: prespecified lag, or vector: of lags to search for. Z is  <br>a matrix<br>+#mTh: combination of lags. Z is one vector-matrix<br>+#thVar: external variable Zis one vector-matrix.<br>+# Default: thDelay=0<br>+	if(!missing(thDelay)) {<br>+		if(max(thDelay)&gt;=m)<br>+			stop(paste(&quot;thDelay too high: should be &lt; m (=&quot;,m,&quot;)&quot;))<br>+		if(model==&quot;TAR&quot;){<br>+			z &lt;- xx<br>+			z2&lt;-embedd(x, lags=c((0:(m-1))*(-d), steps) )[,1:m,drop=FALSE]<br>+			z4&lt;-embed(x,m+1)[,-1]<br>+		}<br>+		else{<br>+			if(thDelay==m-1)<br>+				stop(&quot;th Delay too high, should be &lt;m-1 (=&quot;,m,&quot;)(because of  <br>differencing)&quot;)<br>+ 		z&lt;-embed(diff(x),m)[,thDelay+2]<br>+		#print(cbind(yy,xx,z))<br>+		#z&lt;-z[if(m-thDelay-2&gt;0)-seq_len(m-thDelay-2&gt;0) else  <br>seq_len(nrow(z)),thDelay+2]<br>+		}<br>+	}<br>+ 	else if(!missing(mTh)) {<br>+		if(length(mTh) != m)<br>+			stop(&quot;length of &#39;mTh&#39; should be equal to &#39;m&#39;&quot;)<br>+		z &lt;- xx %*% mTh #threshold variable<br>+		dim(z) &lt;- NULL<br>+	} else if(!missing(thVar)) {<br>+		if(length(thVar)&gt;nrow(xx)) {<br>+			z &lt;- thVar[seq_len(nrow(xx))]<br>+			if(trace)<br>+				cat(&quot;Using only first&quot;, nrow(xx), &quot;elements of thVar
&quot;)<br>+		}<br>+		else<br>+			z &lt;- thVar<br>+		externThVar &lt;- TRUE<br>+	} else {<br>+		z &lt;- xx<br>+	}<br>+<br>+<br>+z&lt;-as.matrix(z)<br>+<br>+### selectSETAR 3: set-up of the grid<br>+#Possibilities:<br>+#gamma pre-specified<br>+#interval to search inside given by user<br>+#value to search around	given by user<br>+#Default method: grid from lower to higher point<br>+  allTh &lt;- sort(z[,1])<br>+  th&lt;-makeTh(allTh=allTh, trim=trim, th=th,ngrid=&quot;ALL&quot;, trace=trace,  <br>nthresh=nthresh)<br>+<br>+### selectSETAR 4: Sets up functions to compute the SSR/AIC/Pooled-AIC for  <br>th= 1 or 2<br>+#have been moved to miscSETAR.R, call before functions to build the  <br>regressors matrix<br>+### selectSETAR 4b:Function pooled AIC<br>+pooledAIC &lt;- function(parms) {	<br>+	nParms&lt;-length(parms)<br>+	thDelayVal &lt;- parms[1] + 1<br>+	mLVal &lt;- parms[2]<br>+	mHVal &lt;- parms[nParms-1]<br>+	m &lt;- max(thDelayVal, mLVal, mHVal)<br>+	lags &lt;- c( (seq_len(m)-1) * (-d), steps)<br>+<br>+	xxyy &lt;- embedd(x, lags = lags)<br>+<br>+	z &lt;- xxyy[, thDelayVal]<br>+	isLow &lt;- (z &lt;= parms[nParms])<br>+<br>+	if ((sum(isLow) &lt; mLVal) | (sum(!isLow) &lt; mHVal))<br>+	    return(NA)<br>+<br>+	xx &lt;- xxyy[isLow, seq_len(mLVal)]<br>+	y &lt;- xxyy[isLow, m + 1]<br>+	AIC1 &lt;- AIC(lm(y ~ xx))<br>+<br>+	xx &lt;- xxyy[!isLow, seq_len(mHVal)]<br>+	y &lt;- xxyy[!isLow, m + 1]<br>+	AIC2 &lt;- AIC(lm(y ~ xx))<br>+	return(AIC1 + AIC2)<br>+}<br>+<br>+<br>+###selectSETAR 5: Grid of combinations of all parameters<br>+  criterion &lt;- match.arg(criterion)<br>+  if(criterion==&quot;SSR&quot;){<br>+    ncombin&lt;-length(thDelay)*length(th)<br>+    if(trace)<br>+      cat(&quot;Searching on &quot;, ncombin, &quot; combinations of threshold and  <br>thDelay
&quot;, sep=&quot;&quot;)<br>+    IDS &lt;- as.matrix(expand.grid(thDelay, th))<br>+    colnames(IDS)&lt;-c(&quot;thDelay&quot;, &quot;th&quot;)<br>+  }<br>+  else{<br>+    if(same.lags){<br>+      ncombin&lt;-length(thDelay)*length(th)*length(ML)<br>+      if(trace)<br>+	cat(&quot;Searching on &quot;, ncombin, &quot; combinations of threshold, thDelay and m  <br>
&quot;)<br>+      IDS &lt;- as.matrix(expand.grid(thDelay,  ML, th))			<br>+      colnames(IDS)&lt;-c(&quot;thDelay&quot;, &quot;m&quot;, &quot;th&quot;)<br>+    }<br>+    else{<br>+      ncombin&lt;-length(thDelay)*length(th)*length(ML)*length(MH)<br>+      if(trace)<br>+	cat(&quot;Searching on &quot;, ncombin, &quot; combinations of threshold, thDelay, ML  <br>and MM
&quot;)<br>+      IDS &lt;- as.matrix(expand.grid(thDelay,  ML, MH, th))			<br>+      colnames(IDS)&lt;-c(&quot;thDelay&quot;, &quot;mL&quot;, &quot;mH&quot;, &quot;th&quot;)<br>+   }<br>+  }<br>+<br>+<br>+###selectSETAR 6: Computation for 1 thresh<br>+  if (criterion == &quot;pooled-AIC&quot;) {<br>+      computedCriterion &lt;- apply(IDS, 1, pooledAIC)<br>+  }<br>+  else if(criterion==&quot;AIC&quot;){<br>+    mHPos&lt;-ifelse(same.lags, 2,3)<br>+    if(common)<br>+      computedCriterion &lt;- mapply(AIC_1thresh, gam1=IDS[,&quot;th&quot;],  <br>thDelay=IDS[,1],ML=IDS[,2],MH=IDS[,mHPos],  <br>MoreArgs=list(xx=xx,yy=yy,trans=z,const=const,trim=trim,fun=buildXth1Common))<br>+    else<br>+      computedCriterion &lt;- mapply(AIC_1thresh, gam1=IDS[,&quot;th&quot;],  <br>thDelay=IDS[,1],ML=IDS[,2],MH=IDS[,mHPos],  <br>MoreArgs=list(xx=xx,yy=yy,trans=z,const=const,trim=trim,fun=buildXth1NoCommon))<br>+  }<br>+  else if(criterion==&quot;SSR&quot;){<br>+    if(common)<br>+      computedCriterion &lt;- mapply(SSR_1thresh,  <br>gam1=IDS[,2],thDelay=IDS[,1],MoreArgs=list(xx=xx,yy=yy,trans=z, ML=ML,  <br>MH=MH, const=const,trim=trim, fun=buildXth1Common))<br>+    else<br>+      computedCriterion &lt;- mapply(SSR_1thresh,  <br>gam1=IDS[,2],thDelay=IDS[,1],MoreArgs=list(xx=xx,yy=yy,trans=z, ML=ML,  <br>MH=MH, const=const,trim=trim, fun=buildXth1NoCommon))<br>+  }<br>+<br>+###selectSETAR 7: sorts the results to show the best values<br>+  allres &lt;- cbind(IDS, computedCriterion)<br>+  colnames(allres) &lt;- c(colnames(IDS), criterion)<br>+  idSel &lt;- sort(computedCriterion, index = TRUE)$ix<br>+  idSel &lt;- idSel[seq_len(min(ifelse(nthresh==1,10,5), length(idSel)))]<br>+  res &lt;- data.frame(allres[idSel, , drop=FALSE], row.names = NULL,  <br>check.names=FALSE)<br>+<br>+  if(criterion==&quot;SSR&quot;){<br>+    bests&lt;-c(res[1,&quot;thDelay&quot;],res[1,&quot;th&quot;],res[1,criterion])<br>+    names(bests)&lt;-c(&quot;thDelay&quot;, &quot;th&quot;,criterion)<br>+  }<br>+  else{<br>+    if(same.lags){<br>+      bests&lt;-c(res[1,&quot;thDelay&quot;],res[1,&quot;th&quot;],res[1,criterion], res[1, &quot;m&quot;])<br>+      names(bests)&lt;-c(&quot;thDelay&quot;, &quot;th&quot;,criterion, &quot;m&quot;)<br>+    }<br>+    else{<br>+      bests&lt;-c(res[1,&quot;thDelay&quot;],res[1,&quot;th&quot;],res[1,criterion],  <br>res[1, &quot;mL&quot;], res[1,&quot;mH&quot;])<br>+      names(bests)&lt;-c(&quot;thDelay&quot;, &quot;th&quot;,criterion, &quot;mL&quot;, &quot;mH&quot;)<br>+    }<br>+  }<br>+<br>+  firstBests&lt;-bests<br>+###selectSETAR 8: Computation for 2 thresh<br>+#use function condistep (see TVARestim.r) to estimate the second th given  <br>the first<br>+#iterate the algortihm: once the second is estimate, reestimate the first,  <br>and alternatively until convergence<br>+  if(nthresh==2){<br>+    ###trace infos<br>+    if(trace){<br>+      if(criterion==&quot;SSR&quot;)<br>+	cat(&quot;Result of the one threshold search:
  <br>-Thresh: &quot;,res[1,&quot;th&quot;],&quot;	-Delay: &quot;,res[1,&quot;thDelay&quot;],&quot;	-&quot;,criterion,  <br>res[1,criterion], &quot;
&quot; )<br>+      else {<br>+	if(same.lags)<br>+	  cat(&quot;Result of the one threshold search:
  <br>-Thresh: &quot;,res[1,&quot;th&quot;],&quot;	-Delay: &quot;,res[1,&quot;thDelay&quot;],&quot;	-m:&quot;,res[1,&quot;m&quot;], &quot;	-&quot;,criterion,  <br>res[1,criterion], &quot;
&quot; )<br>+	else<br>+	  cat(&quot;Result of the one threshold search:
  <br>-Thresh: &quot;,res[1,&quot;th&quot;],&quot;	-Delay: &quot;,res[1,&quot;thDelay&quot;],&quot;	-mL:&quot;,res[1,&quot;mL&quot;], &quot;	-mH:&quot;,res[1,&quot;mH&quot;],&quot;	-&quot;,criterion,  <br>res[1,criterion], &quot;
&quot; )<br>+      }<br>+    }<br>+<br>+    ###set lags according to first search<br>+    potMM&lt;-list()<br>+<br>+    if(criterion==&quot;AIC&quot;){<br>+      if(same.lags){<br>+	ML&lt;-firstBests[&quot;m&quot;]<br>+	MH&lt;-ML<br>+	potMM[[1]]&lt;-ML<br>+      }<br>+      else{<br>+	ML&lt;-firstBests[&quot;mL&quot;]<br>+	MH&lt;-firstBests[&quot;mH&quot;]<br>+	print(MM)<br>+	for(i in 1:length(MM))<br>+	  potMM[[i]]&lt;-seq_len(MM[i])<br>+      }<br>+    }<br>+    else<br>+      potMM[[1]]&lt;-ML<br>+<br>+    if(common)<br>+      func&lt;-switch(criterion, &quot;AIC&quot; = AIC_2threshCommon, &quot;SSR&quot; =  <br>SSR_2threshCommon)	<br>+    else<br>+      func&lt;-switch(criterion, &quot;AIC&quot; = AIC_2threshNoCommon, &quot;SSR&quot; =  <br>SSR_2threshNoCommon)<br>+<br>+    Bests&lt;-matrix(NA, nrow=length(potMM), ncol=4)<br>+    colnames(Bests)&lt;-c(&quot;th1&quot;, &quot;th2&quot;, criterion, &quot;pos&quot;)<br>+    for(j in 1:length(potMM)){<br>+<br>+      More&lt;-list(yy=yy, xx=xx,trans=z, ML=ML, MH=MH,MM=potMM[[j]],  <br>const=const,trim=trim)<br>+      #first conditional search<br>+      last&lt;-condiStep(allTh,threshRef=res[1,&quot;th&quot;],  <br>delayRef=res[1,&quot;thDelay&quot;], fun=func, trim=trim, trace=trace, More=More)<br>+<br>+      #iterative loop for conditional search<br>+      i&lt;-1	#initialise the loop<br>+      while(i&lt;max.iter){<br>+	      b&lt;-condiStep(allTh,last$newThresh, delayRef=res[1,1], fun=func,  <br>trim=trim, trace=trace, More=More)<br>+	      if(b$SSR&lt;last$SSR){	#minimum still not reached<br>+		      i&lt;-i+1<br>+		      last&lt;-b}<br>+	      else{			#minimum reached<br>+		      i&lt;-max.iter<br>+		      last&lt;-b}<br>+      }<br>+    Bests[j,]&lt;-c(min(c(last$threshRef,  <br>last$newThresh)),max(c(last$threshRef, last$newThresh)), last$SSR,  <br>max(potMM[[j]]))<br>+    }<br>+    if(length(potMM)&gt;1){<br>+      index&lt;-sort(Bests[,3], index=TRUE)$ix<br>+      BestsOrdered&lt;-Bests[index,,drop=FALSE]<br>+      MM&lt;-potMM[[BestsOrdered[1,&quot;pos&quot;]]]<br>+<br>+      res2&lt;-unlist(lapply(potMM, max))[index]<br>+      res2&lt;-cbind(res2,BestsOrdered[,-4])<br>+      colnames(res2)&lt;-c(&quot;mM&quot;, &quot;th1&quot;, &quot;th2&quot;, criterion)<br>+      res2 &lt;- data.frame(res2[1:min(nrow(res2),5),], row.names = NULL,  <br>check.names=FALSE)<br>+    }<br>+    else{<br>+      res2 &lt;- data.frame(Bests[,-4, drop=FALSE], row.names = NULL,  <br>check.names=FALSE)<br>+    }<br>+<br>+    if(length(potMM)&gt;1){<br>+      bests2th&lt;-c(max(MM), res2[1,&quot;th1&quot;],res2[1,&quot;th2&quot;], res2[1,criterion])<br>+      names(bests2th)&lt;-c(&quot;mM&quot;, &quot;th1&quot;,&quot;th2&quot;, criterion)<br>+    }<br>+    else{<br>+      bests2th&lt;-c(res2[1,&quot;th1&quot;],res2[1,&quot;th2&quot;], res2[1,criterion])<br>+      names(bests2th)&lt;-c(&quot;th1&quot;,&quot;th2&quot;, criterion)<br>+    }<br>+<br>+    bests&lt;-c(res[1,&quot;thDelay&quot;], res2[1,&quot;th1&quot;],res2[1,&quot;th2&quot;],  <br>res2[1,criterion])<br>+    names(bests)&lt;-c(&quot;thDelay&quot;,&quot;th1&quot;,&quot;th2&quot;, criterion)<br>+  }<br>+  else {#ntresh!=2<br>+    res2&lt;-NULL<br>+    bests2th&lt;-NULL<br>+  }<br>+###selectSETAR 9: plot of the results of the grid search<br>+if(plot==TRUE){<br>+	allcol &lt;- seq_len(max(thDelay+1)*max(ML)*max(MH))<br>+	col &lt;- switch(criterion,  <br>AIC=allcol, &quot;pooled-AIC&quot;=allcol,&quot;SSR&quot;=(thDelay+1) )<br>+	big &lt;- apply(expand.grid(thDelay,ML, MH),1,function(a) paste(&quot;Th:&quot;,  <br>a[1],&quot;mL:&quot;, a[2], &quot;mH:&quot;, a[3]))<br>+	legend &lt;-  <br>switch(criterion, &quot;AIC&quot;=big, &quot;pooled-AIC&quot;=big, &quot;SSR&quot;=paste(&quot;Threshold  <br>Delay&quot;, thDelay))<br>+<br>+	plot(allres[,&quot;th&quot;], allres[,ncol(allres)], col=col, xlab=&quot;Treshold  <br>Value&quot;,ylab=criterion, main=&quot;Results of the grid search&quot;)<br>+ 	legend(&quot;topleft&quot;, pch=1, legend=legend, col=col, bg=0)<br>+}<br>+<br>+###selectSETAR 10: return results<br>+<br>+ret&lt;-list(res=res, res2=res2,bests=bests, th=getTh(bests),  <br>nthresh=nthresh, allTh=allres, criterion=criterion,firstBests=firstBests,  <br>bests2th=bests2th, ML=ML, MM=MM, MH=MH, same.lags=same.lags)<br>+class(ret)&lt;-&quot;selectSETAR&quot;<br>+return(ret)<br>+}<br>+<br>+print.selectSETAR&lt;-function(x,...){<br>+  cat(&quot;Results of the grid search for 1 threshold
